param([Parameter(Mandatory=$true)][ValidateSet('A','B')][string]$Group)
$ErrorActionPreference='Stop';$root='D:\musicclaude\_dl_latest_zip_work';Set-Location -LiteralPath $root
$env:CODEX_HOME=if($Group -eq 'A'){Join-Path $env:USERPROFILE '.codex'}else{Join-Path $env:USERPROFILE '.codex-web'}
$manifest=Get-Content -LiteralPath (Join-Path $root 'jobs\reviews\review_manifest.json') -Raw|ConvertFrom-Json
$eligible=@()
foreach($model in @('gpt56w','gpt6w')){$queue=@($manifest.jobs|Where-Object judge_model -eq $model);for($i=0;$i-lt $queue.Count;$i++){$job=$queue[$i];if(($i%2)-ne $(if($Group -eq 'A'){0}else{1})){continue};if($job.job_id -eq 'G_k18_r01_judgegpt56w_AB'){continue};$base=Join-Path $root (Join-Path ('results\reviews\'+$model) $job.job_id);$metaPath=$base+'.meta.json';if(Test-Path -LiteralPath $metaPath){$meta=Get-Content -LiteralPath $metaPath -Raw|ConvertFrom-Json;if($meta.status -eq 'confirmed_pre_submit_failure' -and $meta.phase -eq 'pre_submit'){$eligible += [pscustomobject]@{job=$job;model=$model;index=$i}}}}}
$log=Join-Path $root ("resume_confirmed_retries_group{0}_progress.log"-f $Group);$runner=Join-Path $root ("resume_confirmed_retries_group{0}.log"-f $Group)
"START $(Get-Date -Format o) profile=$env:CODEX_HOME count=$($eligible.Count)"|Out-File -LiteralPath $log -Encoding utf8
for($n=0;$n-lt $eligible.Count;$n++){$e=$eligible[$n];$id=$e.job.job_id;$model=$e.model;$base=Join-Path $root (Join-Path ('results\reviews\'+$model) $id);$metaPath=$base+'.meta.json';$txtPath=$base+'.txt';$prior=Get-Content -LiteralPath $metaPath -Raw|ConvertFrom-Json;if($prior.status-ne 'confirmed_pre_submit_failure'-or $prior.phase-ne 'pre_submit'){"STOP state changed $id"|Out-File -Append $log;exit 2};"RETRY $($n+1)/$($eligible.Count) $model $id $(Get-Date -Format o)"|Out-File -Append $log -Encoding utf8;& python scripts\run_repeated_trials.py --phase review --round-start 1 --round-end 1 --execute --only-job $id --retry-confirmed-pre-submit >> $runner 2>&1;$code=$LASTEXITCODE;$after=Get-Content -LiteralPath $metaPath -Raw|ConvertFrom-Json;$chars=if(Test-Path -LiteralPath $txtPath){(Get-Item -LiteralPath $txtPath).Length}else{0};"RESULT $id exit=$code status=$($after.status) phase=$($after.phase) chars=$chars $(Get-Date -Format o)"|Out-File -Append $log -Encoding utf8;if($code-ne 0-or $after.status-ne 'success'-or $chars-le 0){"STOP on repeated failure or ambiguity; preserve evidence; no more retries"|Out-File -Append $log;exit 1};Start-Sleep -Seconds 4}
"DONE $(Get-Date -Format o)"|Out-File -Append $log -Encoding utf8
